def Q(q, pt, opts, a, line, why):
    return dict(q=q, pt=pt, opts=[list(o) for o in opts], a=a, line=line, why=why)


def G(q, pt, opts, a, why):
    return dict(q=q, pt=pt, opts=opts, a=a, why=why)


def T(opts, a, why, q='Qual frase está certa?'):
    return dict(q=q, opts=opts, a=a, why=why)


def H(e, x, y, en, pt, say, sayPt):
    return dict(e=e, x=x, y=y, en=en, pt=pt, say=say, sayPt=sayPt)


def EXP(ic, en, tag, pt, use, exen, expt):
    return dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=[exen, expt])


def VBI(v, ic, pt, i_s, he_s, exen, expt, hes):
    return dict(v=v, ic=ic, pt=pt, f=[['eu', i_s], ['ele/ela', he_s]], ex=[exen, expt],
                note='**%s** = %s. Com he/she: **%s**.' % (v, pt, hes))


def MIS(ic, name, desc, prompt, chips, model, check, kw, tips, ok, reply):
    return dict(ic=ic, name=name, desc=desc, data=dict(
        prompt=prompt, ph='Escreva a sua resposta aqui…', chips=chips, model=model, check=check, kw=kw,
        tips=[[list(p) for p in t] for t in tips], ok=ok, reply=list(reply)))


def MOLD(label, slots, end):
    return dict(label=label, slots=[dict(cat=c, opts=[list(o) for o in os]) for c, os in slots], end=list(end))


def RD(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Qual palavra você ouviu?', opts=opts, a=a, why=why)


def HT(say, opts, a, why, ask=None, pic=False):
    d = dict(fig='🎧', say=say, ask=ask or ('Ouça e toque na figura.' if pic else 'Ouça e toque na palavra.'),
             opts=[[o, ''] for o in opts] if pic else opts, a=a, why=why)
    if pic:
        d['pic'] = 1
    return d


def CXI(text, pt, right, w1, w2):
    return dict(text=text, pt=pt, opts=[right, w1, w2], a=0)


def RSd(review, dquiz, rdg, pat, vplay, build, order, soundlab, produce, wrap, dictate):
    return dict(review=review, dquiz=dquiz, rdg=rdg, pat=pat, vplay=vplay, build=build, order=order,
                soundlab=soundlab, produce=produce, wrap=wrap, dictate=dictate)


def ep(n, title, sub, label, why, vocab, balloons, cover, cover_sub, cover_say, recap, teaser, cast, lines, quiz, rdg,
       dictate, produce, rs, sc, names, stage, obra, gancho, hot, gap, trap, sticker, speakers, rule, mission_ic,
       exp, exp_scene, lab, hunt, vb, mold, speak, mtrap, mgap, expq, missions, cx):
    B = dict(title=title, sub=sub, pattern_label=label, why=why, vocab=[list(v) for v in vocab],
             balloons=[list(b) for b in balloons], cover_art=cover, cover_sub=cover_sub, cover_say=cover_say,
             wrap_recap=[list(r) for r in recap], teaser=teaser, cast=cast, lines=[list(l) for l in lines],
             quiz=quiz, rdg_q=rdg, dictate=[list(d) for d in dictate], produce=produce, rs=rs, sc=sc)
    X = dict(n=n, review=True, names=names, stage=stage, obra=obra, gancho=gancho, hot=hot, gap=gap, trap=trap,
             sticker=sticker, speakers=speakers, rule=rule, mission_ic=mission_ic)
    XT = dict(exp=exp, exp_scene=exp_scene, lab=lab, hunt=hunt)
    VB = vb
    MR = dict(mold=mold, speak=[list(s) for s in speak], trap=mtrap, gap=mgap, expq=expq, missions=missions)
    return dict(B=B, X=X, XT=XT, VB=VB, MR=MR, CX=cx)


def PR(prompt, ph, chips, model, check, kw, tips, ok, reply):
    return dict(prompt=prompt, ph=ph, chips=chips, model=model, check=check, kw=kw,
                tips=[[list(p) for p in t] for t in tips], ok=ok, reply=list(reply))


